      "originalUrl": "https://upload.wikimedia.org/wikipedia/commons/1/19/Millennium_Square%2C_Chicago%2C_Illinois_%289181701264%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original",
      "downloadUrl": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Millennium_Square%2C_Chicago%2C_Illinois_%289181701264%29.jpg/960px-Millennium_Square%2C_Chicago%2C_Illinois_%289181701264%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail",
      "author": "Ken Lund from Reno, Nevada, USA",
      "license": "CC BY-SA 2.0",
      "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0",
      "description": "Millennium Park is a public park located in the Loop community area of Chicago in Illinois, USA and originally intended to celebrate the millennium. It is a prominent civic center near the city's Lake Michigan shoreline that covers a 24.5-acre (99,000 m2) section of northwestern Grant Park. The area was previously occupied by parkland, Illinois Central rail yards, and parking lots. The park, which is bounded by Michigan Avenue, Randolph Street, Columbus Drive and East Monroe Drive, features a variety of public art. As of 2009, Millennium Park trailed only Navy Pier as a Chicago tourist attraction.\nPlanning of the park began in October 1997. Construction began in October 1998, and Millennium Park was opened in a ceremony on July 16, 2004, four years behind schedule. The three-day opening celebrations were attended by some 300,000 people and included an inaugural concert by the Grant Park Orchestra and Chorus. The park has received awards for its accessibility and green design. Millennium Park has free admission, and features the Jay Pritzker Pavilion, Cloud Gate, the Crown Fountain, the Lurie Garden, and various other attractions. The park is connected by the BP Pedestrian Bridge and the Nichols Bridgeway to other parts of Grant Park. Because the park sits atop a parking garage and the commuter rail Millennium Station, it is considered the world's largest rooftop garden.\nen.wikipedia.org/wiki/Millennium_Park\n\nen.wikipedia.org/wiki/Wikipedia:Text_of_Creative_Commons_...",
