      "license": "CC BY-SA 4.0",
      "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0",
      "description": "Covering an area of 430 rai, Benjakiti Park lies at the heart of the city on Ratchadapisek road, Khlong Toei district. This area was once an artificial lake, a result from excavation for factory construction, belonging toTheThailand TobaccoMonopoly. After the factory was relocated, this place was developed into a green area for Bangkokians in order to celebrate HRH Queen Sirikit’s 60th birthday anniversary in 1992. Queen Sirikit named this park “Benjakiti”, and designed herself a model of a garden as well as flowering and ornamental plants to be grown each month. The official opening ceremony was held on 9th December, 2004, presided over by the queen.\nThe park is divided into 2 parts: the first part comprises Benjakiti field, a large area which connects both a jogging track and a cycling track and features “Pathum Chat”, a blooming golden lotus sculpture on the topmost post.; a field for activities associated with traditions, art and culture, traditional games, and an area of a Buddha statue “Phra Phuttha Wisuthi Mongkol”; the second part features the Bangkok’s first and largest aqua park, covering two third of the part, with a large lake under the concept “Forest Preserving Water” and small forest parks resembling actual ones in each region.",
